CREATE TABLE IF NOT EXISTS schools(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,code TEXT UNIQUE NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS school_members(school_id INTEGER NOT NULL,user_id INTEGER NOT NULL,joined INTEGER NOT NULL,PRIMARY KEY(school_id,user_id));
CREATE TABLE IF NOT EXISTS licenses(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,school_id INTEGER,plan TEXT NOT NULL,expires INTEGER NOT NULL,source TEXT,note TEXT,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS lic_u ON licenses(user_id);CREATE INDEX IF NOT EXISTS lic_s ON licenses(school_id);
